from pathlib import Path
import hashlib
root=Path('docs')
p=root/'usage-hours.js'
s=p.read_text()
assert hashlib.sha256(p.read_bytes()).hexdigest()=='b0920a7e4888548fd38f744f6ee03d8743156531bcc31f34bc7dfb157e8ea17b'
patches=[(" const sheetKey=k=>k==='labor'||k==='dispatch'?'laborSheets':k==='vehicle'?'vehicleSheets':'equipmentSheets';", " const sheetKey=k=>k==='labor'||k==='dispatch'?'laborSheets':k==='vehicle'?'vehicleSheets':'equipmentSheets';\n // Optional paid tolls are facts per employee / site / day, not hourly rates.\n // Old missing fields remain absent. Identical reported tolls are counted once;\n // disagreements hold only the toll component, never change the labor hours.\n function highwayAmount(a){\n  const raw=a?.highway;\n  if(raw==null||String(raw).trim()==='')return {present:false,value:0,issue:''};\n  const text=String(raw).normalize('NFKC').trim(),value=Number(text);\n  if(typeof raw==='boolean'||!/^\\d+(?:\\.\\d{1,2})?$/.test(text)||!Number.isFinite(value)||value<0||value>1000000000)\n   return {present:true,value:null,issue:'高速代は0以上の金額（小数2桁まで）で入力してください。'};\n  return {present:true,value:round(value),issue:''};\n }\n function highwayEntryError(e){\n  return e.kind==='labor'?arr(e.allocations).map(a=>highwayAmount(a).issue).find(Boolean)||'':'';\n }\n function resolveLaborHighway(g,site){\n  const values=arr(g.claims).flatMap(c=>arr(c.e.allocations).filter(a=>norm(a.site)===norm(site)).map(highwayAmount)).filter(x=>x.present);\n  if(!values.length)return {present:false,value:0,issue:''};\n  const invalid=values.find(x=>x.issue);if(invalid)return invalid;\n  if(new Set(values.map(x=>x.value)).size>1)return {present:true,value:null,issue:'同じ人・日・現場の高速代が日報間で異なります。高速代のみ計上を保留しています。'};\n  return values[0];\n }\n function keepHighway(entry,next){\n  const previous=arr(entry.allocations).find(a=>norm(a.site)===norm(next.site));\n  return entry.kind==='labor'&&previous&&Object.hasOwn(previous,'highway')?{...next,highway:previous.highway}:next;\n }"), ('const entered=next.allocations.filter(a=>a.minutes!==0||a.clock);', "const entered=next.allocations.filter(a=>a.minutes!==0||a.clock||(entry.kind==='labor'&&highwayAmount(a).present&&highwayAmount(a).value!==0));"), ('    let travel=0,highway=0;', "    let travel=0,highway=0;\n    if(g.kind==='labor'){\n     const toll=resolveLaborHighway(g,site.name);highway=toll.value;\n     if(toll.issue){pending.push(g.label+'の高速代');issues.add(date+'：'+g.label+'／'+toll.issue);}\n    }"), ('const engine=Object.freeze({workMinutes,validateEntry,syncEntrySites,', 'const engine=Object.freeze({highwayAmount,resolveLaborHighway,keepHighway,workMinutes,validateEntry,syncEntrySites,'), ('    (labor?premiumHTML(a,i,pfx)+', '    (kind===\'labor\'?\'<label class="uh-highway">高速代（円）<input data-stepper="1" data-uh-highway="\'+i+\'" type="number" inputmode="decimal" min="0" max="1000000000" step="0.01" aria-label="\'+pfx+\' 高速代（円）" value="\'+esc(a.highway??\'\')+\'" placeholder="利用した金額を入力"></label><p class="note uh-highway-note">この現場分の合計額。同じ車の高速代は支払った人の欄に1回だけ。派遣・経費欄との重複に注意。</p>\':\'\')+\n    (labor?premiumHTML(a,i,pfx)+'), ("const message=validateEntry(e)||'合計 '", "const message=highwayEntryError(e)||validateEntry(e)||'合計 '"), ("q('.uh-note',row).textContent=validateEntry(e)||", "q('.uh-note',row).textContent=highwayEntryError(e)||validateEntry(e)||"), ('.uh-inline .note{margin:8px 0 0}', '.uh-inline .note{margin:8px 0 0}.uh-inline .uh-highway{display:block;margin-top:12px}.uh-inline .uh-highway-note{font-size:12px;line-height:1.5}'), ('state={};display();}};', "const previous=state;state={};\n    for(const e of sync(originalCollect())){\n     const prior=previous[rid(e.kind,e.label)];if(!prior||e.kind!=='labor')continue;\n     e.allocations=e.allocations.map(a=>keepHighway(prior,a));\n     for(const a of prior.allocations)if(highwayAmount(a).present&&highwayAmount(a).value!==0&&!e.allocations.some(n=>norm(n.site)===norm(a.site)))e.allocations.push({site:a.site,minutes:0,highway:a.highway});\n    }display();}};"), ('e.allocations=[{site:d.site,minutes:m}];', 'e.allocations=[keepHighway(e,{site:d.site,minutes:m})];'), ('e.allocations=[{site:d.site,minutes:shift.minutes,premium:structuredClone(shift.premium)}];', 'e.allocations=[keepHighway(e,{site:d.site,minutes:shift.minutes,premium:structuredClone(shift.premium)})];'), ("  document.addEventListener('input',event=>{\n   if(event.target.matches('.uh-inline [data-uh-premium]'))", "  document.addEventListener('input',event=>{\n   if(event.target.matches('.uh-inline [data-uh-highway]')){\n    const el=event.target,row=el.closest('[data-uh-id]'),entry=state[row.dataset.uhId],a=entry?.allocations[Number(el.dataset.uhHighway)];\n    if(entry?.kind!=='labor'||!a)return;\n    if(el.value==='')delete a.highway;else a.highway=el.value;\n    updateRow(row);return;\n   }\n   if(event.target.matches('.uh-inline [data-uh-premium]'))"), ('   for(const e of arr(d.usageHours?.entries)){\n    if(e.allocations', "   if(d.usageHours&&[...document.querySelectorAll('.uh-inline:not([hidden]) [data-uh-highway]')].some(i=>!i.checkValidity())){alert('高速代は0以上の金額で入力してください。');return false;}\n   for(const e of arr(d.usageHours?.entries)){\n    const highwayError=highwayEntryError(e);if(highwayError){alert(e.label+'：'+highwayError);return false;}\n    if(e.allocations"), ("+(workTime.describe(a.premium,{includeRates:false})?'（'+workTime.describe(a.premium,{includeRates:false})+'）':'')).join('／')).join('\\n');return t;};", "+(workTime.describe(a.premium,{includeRates:false})?'（'+workTime.describe(a.premium,{includeRates:false})+'）':'')+(e.kind==='labor'&&highwayAmount(a).present?' ／ 高速代 '+(highwayAmount(a).issue?'要確認':highwayAmount(a).value.toLocaleString('ja-JP')+'円'):'')).join('／')).join('\\n');return t;};"), ("q('#uhEnable').onchange=()=>{enabled=q('#uhEnable').checked;display();};", "q('#uhEnable').onchange=()=>{if(!q('#uhEnable').checked&&Object.values(state).some(e=>e.kind==='labor'&&e.allocations.some(a=>highwayAmount(a).present&&highwayAmount(a).value!==0))){q('#uhEnable').checked=true;alert('高速代が入力されています。金額を消さないため時間入力は有効のままです。不要な高速代は入力欄で確認してください。');return;}enabled=q('#uhEnable').checked;display();};")]
for before,after in patches:
 assert s.count(before)==1, before[:80]
 s=s.replace(before,after,1)
assert hashlib.sha256(s.encode()).hexdigest()=='6954cbfc8a47638dc28bb3e8cf4b4412f015a0f2f50cfa51c7ac337828c4b1b3'
(root/'usage-hours.highway-r1.js').write_text(s)
p=root/'index.html';s=p.read_text()
assert hashlib.sha256(p.read_bytes()).hexdigest()=='6f84d0c435c8f64028df996e00b6053b7249062b376edbe4eb67e380b6a3f708'
assert s.count('<script src="usage-hours.js?v=20260918-crew-movement-v1"></script>')==1
p.write_text(s.replace('<script src="usage-hours.js?v=20260918-crew-movement-v1"></script>','<script src="usage-hours.highway-r1.js?v=20260925-highway-r1"></script>',1))
